<section class="container page-section"><div class="breadcrumbs"><a href="/">Home</a><span>/</span><a href="/products?category=<?= urlencode($product['category']) ?>"><?= e($product['category']) ?></a><span>/</span><span><?= e($product['name']) ?></span></div><div class="product-detail"><div class="detail-image"><img src="<?= e(product_image($product)) ?>" alt="<?= e($product['name']) ?>"><span class="image-caption">A closer look</span></div><div class="detail-copy"><span class="eyebrow"><?= e($product['category']) ?></span><h1><?= e($product['name']) ?></h1><div class="detail-rating"><span class="stars">★★★★★</span><strong><?= number_format((float)$product['rating'],1) ?></strong><a href="#reviews"><?= (int)$product['review_count'] ?> customer reviews</a></div><?php if($product['badge']): ?><span class="detail-badge"><?= e($product['badge']) ?></span><?php endif; ?><div class="detail-price"><?= money($product['price']) ?><?php if($product['compare_at']>$product['price']): ?><del><?= money($product['compare_at']) ?></del><span class="saving">Save <?= money($product['compare_at']-$product['price']) ?></span><?php endif; ?></div><p class="detail-description"><?= e($product['description']) ?></p><div class="stock-line <?= (int)$product['stock']>0?'in-stock':'out-stock' ?>"><?= (int)$product['stock']>0?'✓ In stock — '.(int)$product['stock'].' available':'Currently out of stock' ?></div><ul class="spec-list"><?php foreach(json_decode($product['specs']?:'[]',true)?:[] as $spec): ?><li><span>✓</span><?= e($spec) ?></li><?php endforeach; ?></ul><div class="purchase-box"><div class="delivery-line"><span>↗</span><div><strong>Delivery options</strong><small>Shipping and taxes calculated at checkout.</small></div></div><form action="/cart/add" method="post" class="purchase-form"><?= csrf_field() ?><input type="hidden" name="product_id" value="<?= (int)$product['id'] ?>"><input type="hidden" name="return_to" value="cart"><label>Quantity<select name="quantity"><?php for($i=1;$i<=max(1,min(10,(int)$product['stock']));$i++): ?><option><?= $i ?></option><?php endfor; ?></select></label><button class="btn btn-primary btn-block" <?= (int)$product['stock']<1?'disabled':'' ?>>Add to cart</button></form><?php if(is_logged_in()): ?><form action="/wishlist/toggle" method="post"><?= csrf_field() ?><input type="hidden" name="product_id" value="<?= (int)$product['id'] ?>"><input type="hidden" name="return_to" value="<?= e($_SERVER['REQUEST_URI']??'/') ?>"><button class="btn btn-outline btn-block">♡ Save to wishlist</button></form><?php else: ?><a class="btn btn-outline btn-block" href="/sign-in">♡ Sign in to save</a><?php endif; ?><small class="secure-note">♧ Secure account · Straightforward checkout</small></div></div></div>
<section class="reviews-section" id="reviews"><div class="section-heading"><div><span class="eyebrow">REAL FEEDBACK</span><h2>Customer reviews</h2></div><span class="review-summary"><?= number_format((float)$product['rating'],1) ?> / 5 · <?= count($reviews) ?> written reviews</span></div><?php if(is_logged_in()): ?><form class="review-form" action="/review" method="post"><?= csrf_field() ?><input type="hidden" name="product_id" value="<?= (int)$product['id'] ?>"><h3>Share your experience</h3><div class="review-fields"><label>Rating<select name="rating"><?php for($r=5;$r>=1;$r--): ?><option value="<?= $r ?>"><?= $r ?> stars</option><?php endfor; ?></select></label><label>Review title<input name="title" required maxlength="120" placeholder="Sum it up"></label></div><label>Your review<textarea name="body" required rows="3" maxlength="3000" placeholder="What should other shoppers know?"></textarea></label><button class="btn btn-primary">Submit review</button></form><?php else: ?><p class="review-signin"><a href="/sign-in">Sign in</a> to leave a review.</p><?php endif; ?><?php if(!$reviews): ?><p class="muted">No written reviews yet. Be the first to share your thoughts.</p><?php else: ?><div class="review-list"><?php foreach($reviews as $review): ?><article class="review-item"><div class="review-avatar"><?= e(strtoupper(substr($review['reviewer'],0,1))) ?></div><div><div class="review-byline"><strong><?= e($review['reviewer']) ?></strong><small><?= e(date('M j, Y',strtotime($review['created_at']))) ?></small></div><div class="stars"><?= str_repeat('★',(int)$review['rating']).str_repeat('☆',5-(int)$review['rating']) ?></div><h4><?= e($review['title']) ?></h4><p><?= nl2br(e($review['body'])) ?></p></div></article><?php endforeach; ?></div><?php endif; ?></section><?php $related=array_values(array_filter($related,fn($p)=>(int)$p['id']!==(int)$product['id'])); $related=array_slice($related,0,4); if($related): ?><section class="section"><div class="section-heading"><div><span class="eyebrow">MORE TO EXPLORE</span><h2>You might also like</h2></div></div><div class="product-grid"><?php foreach($related as $product) require VIEW_PATH . '/partials/product-card.php'; ?></div></section><?php endif; ?></section>